import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb.active if wb.active is not None else wb.worksheets[0]

# Unmerge any merged cells in the active sheet.
for merged_range in list(ws.merged_cells.ranges):
    ws.unmerge_cells(str(merged_range))

vws = vals[ws.title]

def normalize_item_no(value):
    if value is None:
        return None
    if isinstance(value, str):
        s = value.strip()
        return s if s else None
    if isinstance(value, float) and value.is_integer():
        return str(int(value))
    return str(value)

def unique_count(row_start, row_end):
    seen = set()
    for row in range(row_start, row_end + 1):
        key = normalize_item_no(vws.cell(row=row, column=5).value)  # Column E
        if key is not None:
            seen.add(key)
    return len(seen)

count_1 = unique_count(2, 10)
count_2 = unique_count(11, 20)
count_3 = unique_count(21, 24)

# Ensure the full answer region is clean, then write only the requested outputs.
for row in range(2, 25):
    ws.cell(row=row, column=8).value = None  # Column H

ws.cell(row=10, column=8).value = count_1
ws.cell(row=20, column=8).value = count_2
ws.cell(row=24, column=8).value = count_3

print("Active sheet:", ws.title)
print("Counts:", count_1, count_2, count_3)

wb.save(OUT)
